// Say “start drawing” to capture Me, then “stop drawing” to finish. Only Me’s path
// is captured; the $1 recognizer names common shapes and one rail follows the path.
const templates = {
  circle: Array.from({length:65},(_,i)=>({x:.5+.42*Math.cos(i*2*Math.PI/64),y:.5+.42*Math.sin(i*2*Math.PI/64)})),
  square: [{x:.15,y:.15},{x:.85,y:.15},{x:.85,y:.85},{x:.15,y:.85},{x:.15,y:.15}],
  triangle: [{x:.5,y:.12},{x:.88,y:.82},{x:.12,y:.82},{x:.5,y:.12}],
};
let drawing=false, stroke=[], rails=[], last=null;
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function resample(points,n=64){
  const p=points.map(q=>({...q})); let length=0;
  for(let i=1;i<p.length;i++) length+=dist(p[i-1],p[i]);
  if(length<1)return p;
  const step=length/(n-1),out=[p[0]];let carry=0;
  for(let i=1;i<p.length&&out.length<n;i++){
    let a=p[i-1],b=p[i],seg=dist(a,b);
    while(seg>0&&carry+seg>=step&&out.length<n){
      const t=(step-carry)/seg,q={x:a.x+t*(b.x-a.x),y:a.y+t*(b.y-a.y)};
      out.push(q);a=q;seg=dist(a,b);carry=0;
    }
    carry+=seg;
  }
  while(out.length<n)out.push({...p[p.length-1]});return out;
}
function normalize(points){
  const p=resample(points),first=p[0];
  const angle=Math.atan2(p.reduce((s,q)=>s+q.y-first.y,0),p.reduce((s,q)=>s+q.x-first.x,0));
  const c=Math.cos(-angle),s=Math.sin(-angle);
  let r=p.map(q=>({x:q.x*c-q.y*s,y:q.x*s+q.y*c}));
  const minX=Math.min(...r.map(q=>q.x)),maxX=Math.max(...r.map(q=>q.x));
  const minY=Math.min(...r.map(q=>q.y)),maxY=Math.max(...r.map(q=>q.y)),size=Math.max(maxX-minX,maxY-minY)||1;
  r=r.map(q=>({x:(q.x-(minX+maxX)/2)/size,y:(q.y-(minY+maxY)/2)/size}));
  const cx=r.reduce((a,q)=>a+q.x,0)/r.length,cy=r.reduce((a,q)=>a+q.y,0)/r.length;
  return r.map(q=>({x:q.x-cx,y:q.y-cy}));
}
function recognize(points){
  const a=normalize(points);let best={name:'freeform shape',score:Infinity};
  for(const [name,t] of Object.entries(templates)){
    const b=normalize(t),score=a.reduce((sum,q,i)=>sum+dist(q,b[i]),0)/a.length;
    if(score<best.score)best={name,score};
  }
  return best.score<.22?best.name:'freeform shape';
}
function makeRails(points){
  rails.forEach(r=>r.remove());rails=[];
  // One capped rail follows only the path captured from Me.
  const path=resample(points,8);
  rails=[panto.rail(path,{strength:5,name:'Shape path',handles:'me'})];
}
function finish(){
  if(!drawing)return;
  drawing=false;
  if(stroke.length<5){stroke=[];return speak('Draw a little longer.',{interrupt:true});}
  const name=recognize(stroke);makeRails(stroke);stroke=[];
  speak(name+'. Follow the rail to feel your shape.',{interrupt:true});sound.beep(660,100,{volume:.18});
}
function start(){
  if(drawing)return;
  rails.forEach(r=>r.remove());rails=[];
  drawing=true;stroke=[{x:me.position.x,y:me.position.y}];last=stroke[0];
  speak('Drawing started. Say stop drawing when you are done.',{interrupt:true});
}
me.onMove(p=>{
  if(!drawing)return;
  const point={x:p.x,y:p.y};
  if(!last||dist(last,point)>1.5){stroke.push(point);last=point;}
});
voice.intent('start_drawing',{examples:['start drawing','begin drawing','start shape'],interim:false,onMatch:start});
voice.intent('stop_drawing',{examples:['stop drawing','finish drawing','done drawing','finish shape'],interim:false,onMatch:finish});

speak('Say start drawing, then draw with Me. Say stop drawing to recognize your shape and create its rail.');
